const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const arabianSea = ee.Geometry.Polygon([
    [[50, 25], [78, 25], [78, 5], [50, 5], [50, 25]]
  ]);

  const startDate = '2023-06-01';
  const endDate = '2023-07-01';
  const threshold = 30; // 30°C threshold

  // 2. Data Acquisition - MODIS Terra Sea Surface Temperature
  const sstCollection = ee.ImageCollection('MODIS/061/MOD28')
    .filterDate(startDate, endDate)
    .filterBounds(arabianSea);

  // Check if collection has data
  const collectionSize = sstCollection.size().getInfo();
  console.log(`June 2023 SST Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create monthly composite and calculate mean SST
  const monthlySST = sstCollection.mean();

  // Calculate pixel count to check for valid data
  const pixelCount = monthlySST.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: arabianSea,
    scale: 4000,
    maxPixels: 1e9
  }).get('sea_surface_temperature').getInfo();

  console.log(`Valid Pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean SST
  const meanSST = monthlySST.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: arabianSea,
    scale: 4000,
    maxPixels: 1e9
  }).get('sea_surface_temperature').getInfo();

  console.log(`Mean SST: ${meanSST ? meanSST.toFixed(2) : 'N/A'}°C`);
  console.log(`Threshold: ${threshold}°C`);

  // 5. Validation & Final Answer
  if (meanSST === null || meanSST === undefined || isNaN(meanSST)) {
    console.log("<answer>C3</answer>");
  } else if (meanSST >= threshold) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
